// Step 1: Read and validate required environment / credential variables
const igUserId = $env.META_IG_USER_ID || '17841400000000000';
const accessToken = $env.META_ACCESS_TOKEN || '';
const autoPublishEnabled = ($env.INSTAGRAM_AUTOPUBLISH_ENABLED || 'false').toLowerCase() === 'true';

if (!accessToken) {
  return [{
    json: {
      status: 'ERROR',
      message: 'META_ACCESS_TOKEN is missing in environment',
      kill_switch_active: !autoPublishEnabled,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ig_user_id: igUserId,
    access_token: accessToken,
    kill_switch_active: !autoPublishEnabled,
    target_account: 'avalia_solar',
    graph_api_version: 'v21.0',
    timestamp: new Date().toISOString()
  }
}];

// Step 3: Validate identity & business profile integrity
const response = $input.first().json;
const initData = $('Init & Environment Check').first().json;

const username = response.username || '';
const isValidAccount = username.toLowerCase() === initData.target_account.toLowerCase();

if (!isValidAccount) {
  throw new Error(`Account verification failed: expected '${initData.target_account}', got '${username}'`);
}

return [{
  json: {
    status: 'SUCCESS',
    verified_account: username,
    account_id: response.id,
    account_name: response.name,
    followers_count: response.followers_count,
    media_count: response.media_count,
    kill_switch_active: initData.kill_switch_active,
    meta_api_healthy: true,
    checked_at: new Date().toISOString()
  }
}];
